from __future__ import annotations

import heapq
from itertools import count


class Helpdesk:
    PRIORITIES = ("normal", "high", "critical")

    def __init__(self) -> None:
        self._customers: dict[str, bool] = {}  # name -> vip
        self._tickets: dict[int, dict] = {}  # id -> ticket info
        self._open_queue: list[tuple] = []  # heap of queued tickets
        self._next_id: int = 1
        self._seq = count()  # fifo tiebreaker

    def add_customer(self, name: str, vip: bool = False) -> None:
        self._customers[name] = bool(vip)

    def open_ticket(self, customer: str, title: str, priority: str = "normal") -> int:
        if not title or not title.strip():
            raise ValueError("title must not be empty")
        if priority not in self.PRIORITIES:
            raise ValueError(f"invalid priority: {priority!r}")
        if customer not in self._customers:
            raise KeyError(f"unknown customer: {customer!r}")

        ticket_id = self._next_id
        self._next_id += 1

        self._tickets[ticket_id] = {
            "customer": customer,
            "title": title,
            "priority": priority,
            "state": "open",
        }
        self._enqueue(ticket_id)
        return ticket_id

    def _enqueue(self, ticket_id: int) -> None:
        t = self._tickets[ticket_id]
        vip = self._customers[t["customer"]]
        priority_rank = -self.PRIORITIES.index(t["priority"])
        # VIPs first (0), then by priority rank (higher priority more negative),
        # then FIFO by insertion sequence.
        heap_key = (0 if vip else 1, priority_rank, next(self._seq), ticket_id)
        heapq.heappush(self._open_queue, heap_key)
        t["state"] = "open"

    def next_ticket(self) -> int | None:
        while self._open_queue:
            _, _, _, ticket_id = heapq.heappop(self._open_queue)
            t = self._tickets[ticket_id]
            if t["state"] == "open":
                t["state"] = "in_progress"
                return ticket_id
        return None

    def close(self, ticket_id: int) -> None:
        if ticket_id not in self._tickets:
            raise KeyError(f"unknown ticket id: {ticket_id!r}")
        self._tickets[ticket_id]["state"] = "closed"

    def reopen(self, ticket_id: int) -> None:
        if ticket_id not in self._tickets:
            raise KeyError(f"unknown ticket id: {ticket_id!r}")
        t = self._tickets[ticket_id]
        if t["state"] == "closed":
            raise ValueError("cannot reopen a closed ticket")
        if t["state"] == "open":
            return  # already queued
        # Re-enqueue a ticket that was in_progress (or was removed from the queue).
        self._enqueue(ticket_id)
